function split(total, n) {
  const base = Math.floor(total / n);
  const remainder = total - base * n;   // 남는 최소 단위
  return Array.from({ length: n }, (_, i) => base + (i < remainder ? 1 : 0));
  // 남는 remainder 개를 앞에서부터 1씩 — 합은 정확히 total
}
// split(1000, 3) → [334, 333, 333], 합 1000 (규칙: 앞사람 우대)

// 계산은 정수로 끝내고, 표시할 때만 포맷
new Intl.NumberFormat('ko-KR', {
  style: 'currency', currency: 'KRW'
}).format(1999990 / 1);      // ₩1,999,990

